"""Server-issued public chat sessions (spec 008 Stage 4: P3, N1). Standard library only.

* Web chat session IDs are generated by the server only: ``web_`` + 192 random bits.
* With every session the server issues a **session token**:
  ``v1.<expiry>.<signature>`` where the signature is
  HMAC-SHA256(chat key, "v1" | session_id | instance_id | expiry).
  The token proves possession of the session for one specific bot; it is
  required to continue a conversation or read its history.
* A client-supplied session ID is never proof of ownership: without a valid,
  unexpired token for the same bot, the request starts a new session.
  IDs not in the server format (e.g. ``discord_<user id>``) are never accepted.
* The chat key is derived from the code HMAC key with a fixed label (key
  separation), so no additional secret is needed.
"""
from __future__ import annotations

import base64
import hashlib
import hmac
import re
import secrets
import time
from typing import Optional

WEB_SESSION_PREFIX = "web_"
_SESSION_RE = re.compile(r"^web_[A-Za-z0-9_-]{32}$")
TOKEN_VERSION = "v1"
TOKEN_TTL_SECONDS = 30 * 24 * 3600
MAX_TOKEN_LENGTH = 200
_KEY_LABEL = b"bitbotpro-chat-session-key-v1"


def derive_key(code_hmac_key: bytes) -> bytes:
    if not code_hmac_key:
        raise ValueError("code HMAC key is required")
    return hmac.new(code_hmac_key, _KEY_LABEL, hashlib.sha256).digest()


def new_session_id() -> str:
    return WEB_SESSION_PREFIX + secrets.token_urlsafe(24)  # 24 bytes -> 32 chars


def is_web_session_id(value) -> bool:
    return isinstance(value, str) and bool(_SESSION_RE.fullmatch(value))


def _signature(key: bytes, session_id: str, instance_id: str, expiry: int) -> str:
    msg = "\x1f".join((TOKEN_VERSION, session_id, instance_id, str(expiry))).encode("utf-8")
    return base64.urlsafe_b64encode(hmac.new(key, msg, hashlib.sha256).digest()).decode().rstrip("=")


def issue_token(key: bytes, session_id: str, instance_id: str, now: Optional[float] = None,
                ttl: int = TOKEN_TTL_SECONDS) -> str:
    expiry = int((now if now is not None else time.time()) + ttl)
    return f"{TOKEN_VERSION}.{expiry}.{_signature(key, session_id, instance_id, expiry)}"


def verify_token(key: bytes, token, session_id, instance_id, now: Optional[float] = None) -> bool:
    """Constant-time check that ``token`` was issued for exactly this web session
    and bot, and has not expired. Never raises on malformed input."""
    if not (isinstance(token, str) and 0 < len(token) <= MAX_TOKEN_LENGTH):
        return False
    if not (is_web_session_id(session_id) and isinstance(instance_id, str) and instance_id):
        return False
    parts = token.split(".")
    if len(parts) != 3 or parts[0] != TOKEN_VERSION or not parts[1].isdigit() or not parts[1].isascii():
        return False
    expiry = int(parts[1])
    expected = _signature(key, session_id, instance_id, expiry)
    same = hmac.compare_digest(expected.encode(), parts[2].encode())
    return same and (now if now is not None else time.time()) < expiry


def resume_or_new(key: bytes, session_id, token, instance_id: str, now: Optional[float] = None):
    """Return ``(session_id, token, resumed)``.

    Resumes only with a valid token for this session and bot; otherwise issues
    a brand-new session (the presented ID is ignored, never reused)."""
    if session_id is not None and verify_token(key, token, session_id, instance_id, now):
        return session_id, token, True
    sid = new_session_id()
    return sid, issue_token(key, sid, instance_id, now), False
